INSERT INTO public.vehicle_models VALUES ('c94bdb81-3213-42ad-9812-44b0b4345e4b', '5171c1a1-0000-4000-8000-000000000001', 's1', 'S1', 'Sinclair S1', 2026, 'sedan', 'Compact Sedan', 'The shortest distance between intention and arrival.', 'Sinclair engineering at its most distilled. The S1 carries the range''s structural rigidity and cabin isolation into a compact footprint.', 3290000, NULL, 10, 'published', NULL, '2026-09-12 16:34:00.358643+00');
INSERT INTO public.vehicle_models VALUES ('747513c1-118e-467c-bf45-ba00b59805b9', '5171c1a1-0000-4000-8000-000000000001', 's3', 'S3', 'Sinclair S3', 2026, 'sedan', 'Sport Sedan', 'Composure, at pace.', 'Rear-biased balance, adaptive damping and a chassis developed for sustained load. The S3 is the range''s driver''s car below the R.', 4690000, NULL, 20, 'published', NULL, '2026-09-12 16:34:00.382712+00');
INSERT INTO public.vehicle_models VALUES ('8a41dba9-1257-4e40-b3f1-385cb981486a', '5171c1a1-0000-4000-8000-000000000001', 's5', 'S5', 'Sinclair S5', 2026, 'suv', 'Premium Mid-Size SUV', 'Room for everything you intended to do.', 'The S5 is the centre of the Sinclair range: a mid-size SUV with the isolation of the executive cars and a cabin sized for real use.', 5290000, NULL, 30, 'published', NULL, '2026-09-12 16:34:00.399479+00');
INSERT INTO public.vehicle_models VALUES ('49104833-f74c-4cbe-a1b5-04bca6a263d1', '5171c1a1-0000-4000-8000-000000000001', 's7', 'S7', 'Sinclair S7', 2026, 'sedan', 'Executive Sedan', 'Arrive unhurried.', 'The S7 is Sinclair''s executive sedan: long wheelbase, air suspension and a rear cabin designed to be worked from.', 7890000, NULL, 40, 'published', NULL, '2026-09-12 16:34:00.42901+00');
INSERT INTO public.vehicle_models VALUES ('435f04f1-99e7-406c-8ff8-780bcb73072d', '5171c1a1-0000-4000-8000-000000000001', 'x7', 'X7', 'Sinclair X7', 2026, 'suv', 'Full-Size Luxury SUV', 'Seven seats, no compromises among them.', 'The X7 carries the S7''s isolation into a three-row body, with a third row sized for adults and air suspension across the range.', 8950000, NULL, 50, 'published', NULL, '2026-09-12 16:34:00.446428+00');
