INSERT INTO public.vehicle_models VALUES ('e418ac4d-8694-44b8-b397-db735b46d417', '5171c1a1-0000-4000-8000-000000000001', 'r', 'R', 'Sinclair R', 2026, 'sedan', 'High Performance Sedan', 'Developed where it is used.', 'The R is the S3 taken to its conclusion: bespoke cooling, a wider track and a powertrain calibrated for repeated full-load running.', 11200000, NULL, 70, 'published', NULL, '2026-09-12 16:34:00.474634+00');
INSERT INTO public.vehicle_models VALUES ('c538cec7-5dba-4c83-9c32-4b8c59d6d2d0', '5171c1a1-0000-4000-8000-000000000001', 't4', 'T4', 'Sinclair T4', 2026, 'pickup', 'Full-Size Pickup', 'Built to be used, finished to be kept.', 'A full-size pickup with a fully boxed frame, 3.5 tonne towing and a cabin built to the standards of the rest of the range.', 6240000, NULL, 80, 'published', NULL, '2026-09-12 16:34:00.485419+00');
